node -e "
const initSqlJs = require('/tmp/node_modules/sql.js');
const fs = require('fs');
initSqlJs().then(SQL => {
  const buf = fs.readFileSync('/workspace/world.db');
  const db = new SQL.Database(buf);
  // Get schema
  const schema = db.exec(\"SELECT sql FROM sqlite_master WHERE name='ts_reminders'\");
  console.log('Schema:', JSON.stringify(schema, null, 2));
  // Get all reminders
  const rows = db.exec('SELECT * FROM ts_reminders');
  console.log('Reminders:', JSON.stringify(rows, null, 2));
});
"

node -e "
const initSqlJs = require('/tmp/node_modules/sql.js');
const fs = require('fs');
const crypto = require('crypto');

initSqlJs().then(SQL => {
  const buf = fs.readFileSync('/workspace/world.db');
  const db = new SQL.Database(buf);

  const reminderId = crypto.randomUUID();
  const content = 'Lunch with Jordan tomorrow at 12:30.';
  const creationTimestamp = 1788228000.0;
  const reminderTimestamp = 1788260400.0;  // 1788228000.0 + 32400

  db.run(
    'INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp) VALUES (?, ?, ?, ?)',
    [reminderId, content, creationTimestamp, reminderTimestamp]
  );

  // Verify
  const result = db.exec('SELECT * FROM ts_reminders WHERE reminder_id = \"' + reminderId + '\"');
  console.log('New reminder added:', JSON.stringify(result[0], null, 2));

  // Save
  const data = db.export();
  const buffer = Buffer.from(data);
  fs.writeFileSync('/workspace/world.db', buffer);
  console.log('Database saved.');
});
"
